def localisations(num):
    out = {}
    for l, (titre, appel) in T.get(num, {}).items():
        out[l] = {"title": (titre + " #Shorts")[:100],
                  "description": f"{titre} {appel} {TAGS[l]}\n\n{LIEN[l]} : https://solfito.com/?lang={l}"}
    return out
